src=src.replace("from scipy.optimize import curve_fit","""
def curve_fit(f,s,v,p0):
    import numpy as np
    Ks=np.exp(np.linspace(np.log(0.1),np.log(1e5),20001))
    best=None
    for K in Ks:
        if len(p0)==2:
            x=s/(K+s); V=(x@v)/(x@x); r=((V*x-v)**2).sum(); p=[V,K]
        else:
            r=((f(s,K)-v)**2).sum(); p=[K]
        if best is None or r<best[0]: best=(r,p)
    return np.array(best[1]),None
""")
